package ed25519

import (
	"crypto/ed25519"
	"encoding/hex"
	"testing"
)

type cctvVector struct {
	tcID    int
	comment string
	pub     string // hex, 32 bytes
	msg     string // hex
	sig     string // hex, 64 bytes
	fdOK    bool   // Firedancer's expected verdict (informational)
}

func TestVectorsCCTV(t *testing.T) {
	c := &Cache{}
	for _, v := range cctvVectors {
		pubRaw, err := hex.DecodeString(v.pub)
		if err != nil || len(pubRaw) != 32 {
			t.Fatalf("tc %d: bad pub hex", v.tcID)
		}
		msg, err := hex.DecodeString(v.msg)
		if err != nil {
			t.Fatalf("tc %d: bad msg hex", v.tcID)
		}
		sig, err := hex.DecodeString(v.sig)
		if err != nil || len(sig) != 64 {
			t.Fatalf("tc %d: bad sig hex", v.tcID)
		}
		var pub [32]byte
		copy(pub[:], pubRaw)

		// Documentation, not an assertion: where the stdlib verdict differs
		// from Firedancer's expectation.
		if want := ed25519.Verify(pubRaw, msg, sig); want != v.fdOK {
			t.Logf("tc %d (%s): stdlib=%v firedancer=%v", v.tcID, v.comment, want, v.fdOK)
		}

		// check asserts package Verify, Cache.Verify beyond the admission
		// threshold, and the Precompute path all equal the active profile's
		// independent reference predicate.
		check(t, c, &pub, msg, sig)
	}
}

